<script lang="ts">export default { inheritAttrs: false };</script>
<script setup lang="ts">
import { caretOffset } from './internal/caret';
import type { MentionOption as Option } from './data-types';

import { useAttrs, getCurrentInstance } from 'vue';
import RenderNode from './internal/RenderNode';
import { ref, computed, nextTick } from 'vue'; import { useFloating, type PopupPlacement } from './internal/floating';
import './styles/theme.css'; import './styles/field.css'; import './styles/floating.css'; import './styles/mentions.css';
const attrs = useAttrs();
const generatedFieldId = `at-field-${getCurrentInstance()?.uid}`;
const fieldId = computed(() => typeof attrs.id === 'string' ? attrs.id : generatedFieldId);
const props = withDefaults(defineProps<{ options: (string | Option)[]; modelValue?: string; defaultValue?: string; prefix?: string | string[]; split?: string; filterOption?: boolean | ((query: string, option: Option) => boolean); notFoundContent?: string; size?: 'sm' | 'md' | 'lg'; label?: string; hint?: string; error?: string; status?: 'error' | 'warning'; popupClassName?: string; popupStyle?: import('vue').CSSProperties; autoSize?: boolean | { minRows?: number; maxRows?: number }; placement?: PopupPlacement; disabled?: boolean; rows?: number; placeholder?: string }>(), { defaultValue: '', prefix: '@', split: ' ', filterOption: true, notFoundContent: '没有匹配的成员', size: 'md', placement: 'bottom-start', rows: 3, placeholder: '输入 @ 提及成员' });
const emit = defineEmits<{ 'update:modelValue': [value: string]; change: [value: string]; select: [option: Option, prefix: string]; search: [query: string, prefix: string] }>(); const inner = ref(props.defaultValue), trigger = ref<{ start: number; end: number; prefix: string; query: string } | null>(null), active = ref(0); const input = ref<HTMLTextAreaElement | null>(null); const caret = ref<{ top: number; left: number; height: number }>(); const value = computed(() => props.modelValue ?? inner.value); const normalized = computed<Option[]>(() => props.options.map(option => typeof option === 'string' ? { value: option, label: option } : option)); const visible = computed(() => normalized.value.filter(option => !trigger.value || props.filterOption === false || (typeof props.filterOption === 'function' ? props.filterOption(trigger.value.query, option) : `${option.value} ${typeof option.label === 'string' ? option.label : ''}`.toLocaleLowerCase().includes(trigger.value.query.toLocaleLowerCase())))); const { anchor, panel, position, id, measure } = useFloating(() => !!trigger.value && !props.disabled, () => props.placement, () => { trigger.value = null; });
function update(next: string) { if (props.modelValue === undefined) inner.value = next; emit('update:modelValue', next); emit('change', next); }
function scan() { if (!input.value) return; const end = input.value.selectionStart; const before = input.value.value.slice(0, end); const prefixes = Array.isArray(props.prefix) ? props.prefix : [props.prefix]; let match: typeof trigger.value = null; for (const prefix of prefixes) { const start = before.lastIndexOf(prefix); if (start >= 0 && (start === 0 || /\s/.test(before[start - 1])) && !/\s/.test(before.slice(start + prefix.length))) { if (!match || start > match.start) match = { start, end, prefix, query: before.slice(start + prefix.length) }; } } trigger.value = match; active.value = 0; if (match) { emit('search', match.query, match.prefix); caret.value = caretOffset(input.value, end); void nextTick(measure); } }
function inputValue(event: Event) { update((event.target as HTMLTextAreaElement).value); scan(); if (props.autoSize && input.value) { const config = typeof props.autoSize === 'object' ? props.autoSize : {}; const lineHeight = parseFloat(getComputedStyle(input.value).lineHeight) || 24; input.value.style.height = 'auto'; input.value.style.height = `${Math.min((config.maxRows ?? Infinity) * lineHeight + 20, Math.max((config.minRows ?? props.rows) * lineHeight + 20, input.value.scrollHeight))}px`; } }
async function choose(option: Option) { const current = trigger.value; if (!current || option.disabled || props.disabled) return; const insert = `${current.prefix}${option.value}${props.split}`; update(value.value.slice(0, current.start) + insert + value.value.slice(current.end)); trigger.value = null; emit('select', option, current.prefix); await nextTick(); input.value?.focus(); input.value?.setSelectionRange(current.start + insert.length, current.start + insert.length); }
function key(event: KeyboardEvent) { if (!trigger.value) return; const enabled = visible.value.map((option, index) => option.disabled ? -1 : index).filter(index => index >= 0); if (['ArrowDown', 'ArrowUp'].includes(event.key)) { event.preventDefault(); active.value = enabled[(enabled.indexOf(active.value) + (event.key === 'ArrowDown' ? 1 : -1) + enabled.length) % enabled.length] ?? -1; } if (event.key === 'Enter' && visible.value[active.value]) { event.preventDefault(); void choose(visible.value[active.value]); } if (event.key === 'Escape') trigger.value = null; }
</script>
<template><div class="at-field" :class="attrs.class" :style="attrs.style"><label v-if="label" :for="fieldId" class="at-field__label">{{ label }}</label><div :class="['at-mentions', `at-mentions--${size}`, { 'at-mentions--open': trigger, 'at-mentions--error': error || status === 'error', 'at-mentions--warning': status === 'warning', 'at-mentions--disabled': disabled }]"><span ref="anchor" class="at-mentions__caret" :style="caret ? { top: `${caret.top}px`, left: `${caret.left}px`, height: `${caret.height}px` } : undefined" /><textarea :id="fieldId" ref="input" v-bind="{ ...attrs, class: undefined, style: undefined }" class="at-mentions__input" :value="value" :disabled="disabled" :rows="rows" :placeholder="placeholder" :aria-label="label ?? placeholder" :aria-expanded="!!trigger" :aria-controls="trigger ? id : undefined" @input="inputValue" @click="scan" @keyup.left="scan" @keyup.right="scan" @keydown="key" /></div><span v-if="error" class="at-field__error" role="alert">{{ error }}</span><span v-else-if="hint" class="at-field__hint">{{ hint }}</span><Teleport to="body"><div v-if="trigger && !disabled" ref="panel" :class="['at-popup', 'at-mentions__popup', popupClassName]" :style="[position, popupStyle]"><ul :id="id" role="listbox" class="at-popup__list"><li v-for="(option, index) in visible" :key="option.value" role="option" :aria-selected="active === index" :aria-disabled="option.disabled" :class="['at-option', { 'at-option--active': active === index, 'at-option--disabled': option.disabled }]" @mousedown.prevent @mouseenter="active = index" @click="choose(option)"><slot name="option" :option="option" :active="active === index" :query="trigger.query"><span v-if="option.avatar" class="at-mentions__avatar"><RenderNode :content="option.avatar" /></span><span v-else class="at-mentions__avatar at-mentions__avatar--initial">{{ option.value.slice(0, 1).toUpperCase() }}</span><span class="at-option__label"><span><RenderNode :content="option.label ?? option.value" /></span><small v-if="option.description"><RenderNode :content="option.description" /></small></span></slot></li><li v-if="!visible.length" class="at-popup__empty">{{ notFoundContent }}</li></ul></div></Teleport></div></template>
